<"'!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>费用分摊计算器</title>
<style>
*{box-sizing:border-box}
body{margin:0;padding:24px;font:16px/1.6 system-ui,-apple-system,"PingFang SC","Microsoft YaHei",sans-serif;background:#f4f6f8;color:#1f2933}
.card{max-width:420px;margin:0 auto;background:#fff;padding:24px;border-radius:14px;box-shadow:0 6px 20px rgba(0,0,0,.08)}
h1{margin:0 0 4px;font-size:22px}
.sub{margin:0 0 18px;font-size:14px;color:#6b7280}
label{display:block;margin:14px 0 6px;font-size:14px;color:#374151}
input{width:100%;padding:10px 12px;font-size:16px;border:1px solid #d1d5db;border-radius:8px;background:#fff;color:#111}
input:focus{outline:2px solid #2563eb;border-color:#2563eb}
button{width:100%;margin-top:18px;padding:11px;font-size:16px;font-weight:600;color:#fff;background:#2563eb;border:0;border-radius:8px;cursor:pointer}
button:hover{background:#1d4ed8}
#result{margin-top:18px;padding:14px;border-radius:10px;background:#f3f4f6;min-height:64px}
#result.ok{background:#ecfdf5;color:#065f46}
#result.err{background:#fef2f2;color:#b91c1c}
.amount{font-size:28px;font-weight:700}
.note{margin-top:4px;font-size:13px;opacity:.85}
</style>
</head>
<body>
<div class="card">
<h1>费用分摊计算器</h1>
<p class="sub">输入总金额与参与人数，即刻算出每人应付金额。完全离线，不上传任何数据。</p>
<form id="form" novalidate>
<label for="total">总金额（元）</label>
<input id="total" type="text" inputmode="decimal" placeholder="例如 1200.50" autocomplete="off">
<label for="people">人数</label>
<input id="people" type="text" inputmode="numeric" placeholder="例如 4" autocomplete="off">
<button type="submit">计算每人应付</button>
</form>
<div id="result"><div class="amount" id="per">—</div><div class="note" id="note">等待输入…</div></div>
</div>
<script>
function calc(totalRaw, peopleRaw){
  const t = String(totalRaw == null ? '"'' : totalRaw).trim();
  const p = String(peopleRaw == null ? '' : peopleRaw).trim();
  if(t === '') return {ok:false, msg:'请输入总金额'};
  if(p === '') return {ok:false, msg:'请输入人数'};
  const total = Number(t), people = Number(p);
  if("'!isFinite(total) || !isFinite(people)) return {ok:false, msg:'"'请输入有效的数字'};
  if(total < 0) return {ok:false, msg:'总金额不能为负数'};
  if("'!Number.isInteger(people)) return {ok:false, msg:'"'人数必须是整数'};
  if(people <= 0) return {ok:false, msg:'人数必须大于 0'};
  return {ok:true, total:total, people:people};
}
function split(r){
  const cents = Math.round(r.total * 100);
  const perCents = Math.floor(cents / r.people);
  return {per:perCents / 100, perCents:perCents, remCents:cents - perCents * r.people};
}
function render(){
  const t = el.total.value.trim(), p = el.people.value.trim();
  if(t === '' && p === ''){
    el.result.className = ''; el.per.textContent = '—'; el.note.textContent = '等待输入…'; return;
  }
  const r = calc(t, p);
  if("'!r.ok){
    el.result.className = '"'err'; el.per.textContent = '—'; el.note.textContent = r.msg; return;
  }
  const s = split(r);
  el.result.className = 'ok';
  el.per.textContent = '¥' + (s.perCents / 100).toFixed(2);
  el.note.textContent = s.remCents === 0
    ? '共 ' + r.people + ' 人平摊，合计 ¥' + r.total.toFixed(2)
    : '共 ' + r.people + ' 人平摊，其中 1 人需多付 ¥' + (s.remCents / 100).toFixed(2);
}
const el = {
  form: document.getElementById('form'), total: document.getElementById('total'),
  people: document.getElementById('people'), result: document.getElementById('result'),
  per: document.getElementById('per'), note: document.getElementById('note')
};
el.form.addEventListener('submit', function(e){ e.preventDefault(); render(); });
el.total.addEventListener('input', render);
el.people.addEventListener('input', render);
render();
</script>
</body>
</html>
