'use strict';
/* 离线费用分摊计算器 —— Node 端验证脚本（vm + 简易 DOM 桩，不使用浏览器） */
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const ROOT = __dirname;
const HTML_PATH = path.join(ROOT, 'artifacts', 'index.html');
const OUT_PATH = path.join(ROOT, 'artifacts', 'verification.txt');

const results = [];
function check(name, fn) {
  try {
    const detail = fn();
    results.push({ name, pass: true, detail: detail || 'ok' });
  } catch (err) {
    results.push({ name, pass: false, detail: (err && err.message) || String(err) });
  }
}
function assert(cond, msg) { if ("'!cond) throw new Error(msg || '"'断言失败'); }
function eq(actual, expected, msg) {
  if (actual "'!== expected) throw new Error((msg || '"'值不相等') + '：期望 ' + JSON.stringify(expected) + '，实际 ' + JSON.stringify(actual));
}
function near(actual, expected, eps, msg) {
  if ("'!(Math.abs(actual - expected) <= eps)) throw new Error((msg || '"'数值不接近') + '：期望约 ' + expected + '，实际 ' + actual);
}

/* ---------- 读取页面并提取内联脚本 ---------- */
const html = fs.readFileSync(HTML_PATH, 'utf8');
const lineCount = html.replace(/\\n"'$/, '"'').split('\\n').length;
const scriptMatch = /<script>([\\s\\S]*?)<\\/script>/.exec(html);
if ("'!scriptMatch) throw new Error('"'未找到内联 <script> 块');
const inlineScript = scriptMatch[1];

/* ---------- 简易 DOM 桩 ---------- */
function createElement(id) {
  return {
    id, value: '', textContent: '', className: '', listeners: {},
    addEventListener(type, fn) { (this.listeners[type] = this.listeners[type] || []).push(fn); },
    dispatch(type, extra) {
      const evt = Object.assign({ type, defaultPrevented: false, preventDefault() { evt.defaultPrevented = true; } }, extra || {});
      (this.listeners[type] || []).forEach(fn => fn.call(this, evt));
      return evt;
    }
  };
}
const IDS = ['form', 'total', 'people', 'result', 'per', 'note'];
const elements = {};
IDS.forEach(id => { elements[id] = createElement(id); });
const documentStub = {
  getElementById(id) { return elements[id] || null; },
  querySelector() { return null; },
  addEventListener() {},
  body: createElement('body')
};

/* ---------- 在 vm 中执行内联脚本 ---------- */
const sandbox = { document: documentStub, console };
sandbox.window = sandbox;
sandbox.self = sandbox;
vm.createContext(sandbox);
vm.runInContext(inlineScript, sandbox, { filename: 'artifacts/index.html#inline-script' });
const calc = sandbox.calc;
const split = sandbox.split;
assert(typeof calc === 'function', '内联脚本未导出 calc 函数');
assert(typeof split === 'function', '内联脚本未导出 split 函数');

function setForm(total, people) {
  elements.total.value = total;
  elements.people.value = people;
  elements.total.dispatch('input');
}

/* ---------- 结构 / 离线自洽检查 ---------- */
check('HTML 总行数 ≤ 100（实际 ' + lineCount + ' 行）', () => {
  assert(lineCount <= 100, '行数 ' + lineCount + ' 超过 100 行');
  return '实际 ' + lineCount + ' 行';
});
check('CSS 与 JS 全部内联（无 <link>、无外部 script src）', () => {
  assert(/<style>[\\s\\S]*<\\/style>/.test(html), '缺少内联 <style>');
  assert(/<script>[\\s\\S]*<\\/script>/.test(html), '缺少内联 <script>');
  assert("'!/<link'"\\b/i.test(html), '存在外部样式表 <link>');
  assert("'!/<script[''^>]+src=/i.test(html), '"'存在外部脚本引用');
  return '内联 style + script';
});
check('不依赖外网（无 http(s) 链接、无网络 API）', () => {
  assert("'!/https?:'"\\/\\//i.test(html), '页面包含 http(s) 外部地址');
  assert("'!/'"\\bfetch\\s*\\(|XMLHttpRequest|WebSocket|EventSource|navigator\\.sendBeacon/.test(html), '页面包含网络调用');
  return '无外部地址与网络调用';
});
check('关键中文文案齐全', () => {
  ['费用分摊计算器', '总金额', '人数', '每人应付', '不能为负数', '必须大于 0', '有效的数字'].forEach(t => {
    assert(html.includes(t), '缺少文案：' + t);
  });
  return '7 项文案均存在';
});
check('脚本引用的 DOM id 均在 HTML 中存在', () => {
  const ids = [...inlineScript.matchAll(/getElementById\\('(["'^'"']+)'\\)/g)].map(m => m[1]);
  assert(ids.length > 0, '未解析到任何 getElementById');
  ids.forEach(id => assert(html.includes('id=\"' + id + '\"'), '缺少 id=\"' + id + '\"'));
  return '校验 ' + ids.length + ' 个 id：' + ids.join(', ');
});

/* ---------- calc() 纯函数单元测试 ---------- */
check('calc：1200 元 / 4 人 → 每人 300', () => {
  const r = calc('1200', '4');
  assert(r.ok === true, '期望校验通过，实际：' + r.msg);
  near(split(r).per, 300, 1e-9, '每人金额错误');
  return '每人 ¥300.00';
});
check('calc：100 元 / 3 人 → 每人 ¥33.33，余 ¥0.01', () => {
  const r = calc('100', '3');
  assert(r.ok === true, '期望校验通过，实际：' + r.msg);
  const s = split(r);
  eq(s.perCents, 3333, '每人分（分）错误');
  eq(s.remCents, 1, '余数（分）错误');
  return '每人 ¥33.33，余 ¥0.01';
});
check('calc：0.3 元 / 3 人 → 每人 ¥0.10（整数分避免浮点误差）', () => {
  const s = split(calc('0.3', '3'));
  eq(s.perCents, 10, '每人分（分）错误');
  eq(s.remCents, 0, '余数（分）错误');
  return '每人 ¥0.10';
});
check('calc：0 元 / 4 人 → 每人 ¥0.00', () => {
  const r = calc('0', '4');
  assert(r.ok === true, '期望校验通过，实际：' + r.msg);
  eq(split(r).perCents, 0, '每人分（分）错误');
  return '每人 ¥0.00';
});
check('calc：人数为 0 → 拒绝并提示人数', () => {
  const r = calc('100', '0');
  assert(r.ok === false, '应判为无效');
  assert(r.msg.includes('人数'), '提示应包含\"人数\"，实际：' + r.msg);
  return r.msg;
});
check('calc：人数为负数 → 拒绝并提示人数', () => {
  const r = calc('100', '-3');
  assert(r.ok === false, '应判为无效');
  assert(r.msg.includes('人数'), '提示应包含\"人数\"，实际：' + r.msg);
  return r.msg;
});
check('calc：负金额 → 拒绝并提示不能为负数', () => {
  const r = calc('-50', '4');
  assert(r.ok === false, '应判为无效');
  assert(r.msg.includes('负'), '提示应包含\"负\"，实际：' + r.msg);
  return r.msg;
});
check('calc：金额为非数字 → 拒绝并提示有效的数字', () => {
  const r = calc('abc', '4');
  assert(r.ok === false, '应判为无效');
  assert(r.msg.includes('有效'), '提示应包含\"有效\"，实际：' + r.msg);
  return r.msg;
});
check('calc：Infinity / NaN → 拒绝并提示有效的数字', () => {
  const a = calc('Infinity', '2'), b = calc('NaN', '2');
  assert(a.ok === false && b.ok === false, '应判为无效');
  assert(a.msg.includes('有效') && b.msg.includes('有效'), '提示应包含\"有效\"');
  return 'Infinity 与 NaN 均被拒绝';
});
check('calc：人数为小数 → 拒绝并提示整数', () => {
  const r = calc('100', '2.5');
  assert(r.ok === false, '应判为无效');
  assert(r.msg.includes('整数'), '提示应包含\"整数\"，实际：' + r.msg);
  return r.msg;
});
check('calc：总金额为空 → 拒绝并提示请输入总金额', () => {
  const r = calc('', '4');
  assert(r.ok === false, '应判为无效');
  assert(r.msg.includes('总金额'), '提示应包含\"总金额\"，实际：' + r.msg);
  return r.msg;
});
check('calc：人数为空 → 拒绝并提示请输入人数', () => {
  const r = calc('100', '');
  assert(r.ok === false, '应判为无效');
  assert(r.msg.includes('人数'), '提示应包含\"人数\"，实际：' + r.msg);
  return r.msg;
});
check('calc：首尾空白被忽略（\"  50  \" / \"  4  \"）', () => {
  const r = calc('  50  ', '  4  ');
  assert(r.ok === true, '期望校验通过，实际：' + r.msg);
  near(split(r).per, 12.5, 1e-9, '每人金额错误');
  return '每人 ¥12.50';
});
check('calc：科学计数法 \"1e3\" / 2 人 → 每人 ¥500.00', () => {
  const r = calc('1e3', '2');
  assert(r.ok === true, '期望校验通过，实际：' + r.msg);
  near(split(r).per, 500, 1e-9, '每人金额错误');
  return '每人 ¥500.00';
});

/* ---------- DOM 集成测试 ---------- */
check('初始渲染：显示\"等待输入…\"且无结果样式', () => {
  eq(elements.per.textContent, '—', '金额占位错误');
  eq(elements.note.textContent, '等待输入…', '提示文案错误');
  eq(elements.result.className, '', '结果区不应带有状态样式');
  return '初始状态正确';
});
check('DOM：100 / 3 → 显示 ¥33.33 并提示余 ¥0.01', () => {
  setForm('100', '3');
  eq(elements.per.textContent, '¥33.33', '金额显示错误');
  eq(elements.result.className, 'ok', '结果状态样式应为 ok');
  assert(elements.note.textContent.includes('0.01'), '提示应说明余 ¥0.01，实际：' + elements.note.textContent);
  return elements.per.textContent + ' / ' + elements.note.textContent;
});
check('DOM：1200.50 / 4 → 显示 ¥300.12 并提示余 ¥0.02', () => {
  setForm('1200.50', '4');
  eq(elements.per.textContent, '¥300.12', '金额显示错误');
  assert(elements.note.textContent.includes('0.02'), '提示应说明余 ¥0.02，实际：' + elements.note.textContent);
  return elements.per.textContent + ' / ' + elements.note.textContent;
});
check('DOM：1200 / 4 → 显示 ¥300.00 且提示合计', () => {
  setForm('1200', '4');
  eq(elements.per.textContent, '¥300.00', '金额显示错误');
  assert(elements.note.textContent.includes('合计'), '提示应说明合计，实际：' + elements.note.textContent);
  return elements.per.textContent + ' / ' + elements.note.textContent;
});
check('DOM：人数为 0 → 红色错误态且提示人数', () => {
  setForm('100', '0');
  eq(elements.result.className, 'err', '结果状态样式应为 err');
  eq(elements.per.textContent, '—', '金额应回到占位符');
  assert(elements.note.textContent.includes('人数'), '提示应包含\"人数\"，实际：' + elements.note.textContent);
  return elements.note.textContent;
});
check('DOM：负金额 → 红色错误态且提示不能为负数', () => {
  setForm('-10', '4');
  eq(elements.result.className, 'err', '结果状态样式应为 err');
  assert(elements.note.textContent.includes('负'), '提示应包含\"负\"，实际：' + elements.note.textContent);
  return elements.note.textContent;
});
check('DOM：无效输入 \"abc\" → 红色错误态且提示有效的数字', () => {
  setForm('abc', '4');
  eq(elements.result.className, 'err', '结果状态样式应为 err');
  assert(elements.note.textContent.includes('有效'), '提示应包含\"有效\"，实际：' + elements.note.textContent);
  return elements.note.textContent;
});
check('DOM：金额留空、人数填写 → 提示请输入总金额', () => {
  setForm('', '4');
  eq(elements.result.className, 'err', '结果状态样式应为 err');
  assert(elements.note.textContent.includes('总金额'), '提示应包含\"总金额\"，实际：' + elements.note.textContent);
  return elements.note.textContent;
});
check('DOM：点击\"计算\"按钮提交表单 → 阻止跳转并刷新结果', () => {
  setForm('100', '3');
  const evt = elements.form.dispatch('submit');
  eq(evt.defaultPrevented, true, 'submit 事件未调用 preventDefault');
  eq(elements.per.textContent, '¥33.33', '提交后金额未刷新');
  return 'submit 已阻止默认行为，结果正确';
});
