function parseMoney(raw){
  const s=String(raw==null?'':raw).trim().replace(/,/g,'');
  if(s==='')return{ok:false,msg:'请输入总金额'};
  if(s.charAt(0)==='-')return{ok:false,msg:'总金额不能为负数'};
  if(!/^\d*\.?\d*$/.test(s)||!/\d/.test(s))return{ok:false,msg:'请输入有效的数字'};
  const p=s.split('.');
  if((p[1]||'').length>2)return{ok:false,msg:'金额最多保留两位小数'};
  const cents=parseInt(p[0]||'0',10)*100+parseInt((p[1]||'').padEnd(2,'0'),10);
  return Number.isSafeInteger(cents)?{ok:true,cents:cents}:{ok:false,msg:'金额过大，无法精确计算'};
}
